import ast
import math
import operator


# Allowed binary operators
BINARY_OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.Pow: operator.pow,
    ast.Mod: operator.mod,
}

# Allowed unary operators
UNARY_OPERATORS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}

# Supported scientific functions
FUNCTIONS = {
    "sqrt": math.sqrt,
    "sin": math.sin,
    "cos": math.cos,
    "tan": math.tan,
    "asin": math.asin,
    "acos": math.acos,
    "atan": math.atan,
    "sinh": math.sinh,
    "cosh": math.cosh,
    "tanh": math.tanh,
    "log": math.log,       # Natural log, or log(x, base)
    "ln": math.log,
    "log10": math.log10,
    "exp": math.exp,
    "abs": abs,
    "floor": math.floor,
    "ceil": math.ceil,
    "factorial": math.factorial,
    "degrees": math.degrees,
    "radians": math.radians,
}

CONSTANTS = {
    "pi": math.pi,
    "e": math.e,
    "tau": math.tau,
}


def evaluate(node):
    if isinstance(node, ast.Expression):
        return evaluate(node.body)

    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
            return node.value
        raise ValueError("Only numeric constants are allowed.")

    if isinstance(node, ast.BinOp):
        operator_type = type(node.op)

        if operator_type not in BINARY_OPERATORS:
            raise ValueError("Unsupported operator.")

        left = evaluate(node.left)
        right = evaluate(node.right)

        return BINARY_OPERATORS[operator_type](left, right)

    if isinstance(node, ast.UnaryOp):
        operator_type = type(node.op)

        if operator_type not in UNARY_OPERATORS:
            raise ValueError("Unsupported unary operator.")

        return UNARY_OPERATORS[operator_type](evaluate(node.operand))

    if isinstance(node, ast.Name):
        if node.id in CONSTANTS:
            return CONSTANTS[node.id]

        raise ValueError(f"Unknown constant: {node.id}")

    if isinstance(node, ast.Call):
        if not isinstance(node.func, ast.Name):
            raise ValueError("Invalid function call.")

        function_name = node.func.id

        if function_name not in FUNCTIONS:
            raise ValueError(f"Unsupported function: {function_name}")

        if node.keywords:
            raise ValueError("Keyword arguments are not supported.")

        arguments = [evaluate(arg) for arg in node.args]

        return FUNCTIONS[function_name](*arguments)

    raise ValueError("Unsupported expression.")


def execute(input: dict) -> dict:
    query = input.get("query", "")

    if not isinstance(query, str) or not query.strip():
        return {
            "success": False,
            "result": None,
            "error": "A non-empty query is required."
        }

    # Prevent excessively large requests
    if len(query) > 500:
        return {
            "success": False,
            "result": None,
            "error": "Expression is too long."
        }

    try:
        tree = ast.parse(query, mode="eval")
        result = evaluate(tree)

        # Prevent returning NaN/Infinity
        if isinstance(result, float) and not math.isfinite(result):
            raise ValueError("Result is not finite.")

        return {
            "success": True,
            "result": result,
            "error": None
        }

    except ZeroDivisionError:
        return {
            "success": False,
            "result": None,
            "error": "Division by zero."
        }

    except (ValueError, TypeError, OverflowError, SyntaxError) as e:
        return {
            "success": False,
            "result": None,
            "error": str(e)
        }

    except Exception:
        return {
            "success": False,
            "result": None,
            "error": "Unable to evaluate expression."
        }
